head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt76100";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.changeSysTpCd("2");
        scwin.setPeriod($c.util.getComponent('slc_searchYear').getValue());
        await scwin.list();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt76100.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt76100.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_1_onsubmit
 * @description form_1 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_1_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt76100.form_1_onsubmit' }); }
};

/**
 * @method
 * @name slc_notiObjSysTpCd_onchange
 * @description slc_notiObjSysTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_notiObjSysTpCd_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.changeSysTpCd(selfVar.value);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt76100.slc_notiObjSysTpCd_onchange' }); }
};

/**
 * @method
 * @name img_70_onclick
 * @description img_70 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_70_onclick = async function(e){
    try {
        await scwin.list()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt76100.img_70_onclick' }); }
};

/**
 * @method
 * @name img_89_onclick
 * @description img_89 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_89_onclick = async function(e){
    try {
        await scwin.addNotice()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt76100.img_89_onclick' }); }
};

/**
 * @method
 * @name img_90_onclick
 * @description img_90 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_90_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt76100.img_90_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_List_xhr
 * @description List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    let strFlag = "";
    strFlag = $c.util.getComponent("dma_ListXhrReq").get("periodFlag");
    let strtDdtm = $c.util.getComponent('cal_strtDdtm').getValue(); if (strtDdtm == null) { strtDdtm = ''; }
    let endDdtm = $c.util.getComponent('cal_endDdtm').getValue(); if (endDdtm == null) { endDdtm = ''; }
    let strMsg = "";
    if ((strtDdtm === "" || endDdtm === "")) {
        strMsg = "기간 검색시 일자를 반드시 입력하세요";
    }
    if (strtDdtm > endDdtm) {
        strMsg = "시작일은 종료일 이후이여야 합니다";
    }
    if (strFlag === "1" && strMsg !== "") {
        await $c.win.alert(strMsg);
        return;
    }
    scwin.form_listForm.action = "/filing/notice.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "selectNotice");
    $c.util.getComponent('txt_sysListDiv').setValue(await scwin.tx_fn_List_xhr());
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {String} contnId contnId
 * @param {String} title title
 * @param {String} wrtDd wrtDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function (contnId, title, wrtDd) {
    const _confirm = await $c.win.confirm("공지사항 '" + title + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /filing/notice.do?method=deleteNotice&contnId=). 전환 대상 화면이 확정되면 연결됩니다.') + contnId;
};

/**
 * @method
 * @name findNotice
 * @description find Notice 처리
 * @param {String} contnId contnId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findNotice = async function (contnId) {
    const _url = "/filing/updateNotice.do?method=findNotice&contnId=" + contnId + "&mode=update";
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=700,height=300";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "noticePop", popupName: "noticePop", width: "700", height: "600" }, {});
};

/**
 * @method
 * @name addNotice
 * @description add Notice 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addNotice = async function () {
    const _url = "/filing/updateNotice.do?method=findNotice" + "&mode=create";
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=700,height=300";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "noticePop", popupName: "noticePop", width: "700", height: "600" }, {});
};

/**
 * @method
 * @name setPeriod
 * @description set Period 처리
 * @param {*} year year
 * @returns {void}
 * @hidden N
 */
scwin.setPeriod = function (year) {
    $c.util.getComponent("cal_strtDdtm").setValue(year + "-01-01");
    $c.util.getComponent("cal_endDdtm").setValue(year + "-12-31");
};

/**
 * @method
 * @name selectBox1
 * @description select Box1 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectBox1 = function () {
    const date = new Date();
    const thisYear = date.getFullYear();
    const valueCnt = thisYear - 2018;
    let year;
    let selText;
    document.write("<option value=''>-- 선택 --</option>");
    for (let i = 0; i <= valueCnt; i++) {
        selText = "";
        if (i === 0) {
            selText = "selected";
        }
        year = date.getFullYear();
        document.write("<option value='" + year + "' " + selText + ">" + year + "년</option>");
        date.setYear(date.getFullYear() - 1);
    }
};

/**
 * @method
 * @name selectBox2
 * @description select Box2 처리
 * @param {String} sysTpCd sysTpCd
 * @returns {void}
 * @hidden N
 */
scwin.selectBox2 = function (sysTpCd) {
    $('select[name=corpUsrTpCd]').find('option').remove();
    $('select[name=corpUsrTpCd]').append("<option value=''>-- 선택 --</option>");
    $('select[name=corpUsrTpCd]').append("<option value='N'>전체</option>");
    if (sysTpCd === "1") {
        for (let i = 0; i < (function(){ throw 'unresolved:list:corpUsrTpCdList1'; })(); i++) {
            $('select[name=corpUsrTpCd]').append("<option value='${corpUsrTpCdList1[__i].cdVal}'" + "${(noticeDetail.corpUsrTpCd == entity.cdVal )?'selected':''} " + ">${corpUsrTpCdList1[__i].cdValNm}</option>");
        }
    } else {
        if (sysTpCd === "B") {
            for (let i1 = 0; i1 < (function(){ throw 'unresolved:list:corpUsrTpCdList2'; })(); i1++) {
                $('select[name=corpUsrTpCd]').append("<option value='${corpUsrTpCdList2[__i1].cdVal}'" + "${(noticeDetail.corpUsrTpCd == entity.cdVal )?'selected':''} " + ">${corpUsrTpCdList2[__i1].cdValNm}</option>");
            }
        }
    }
};

/**
 * @method
 * @name changeSysTpCd
 * @description change Sys Tp Cd 처리
 * @param {String} sysTpCd sysTpCd
 * @returns {void}
 * @hidden N
 */
scwin.changeSysTpCd = function (sysTpCd) {
    if (sysTpCd === "1" || sysTpCd === "B") {
        ($c.util.getComponent("srch_fil_ods") && $c.util.getComponent("srch_fil_ods").show ? $c.util.getComponent("srch_fil_ods").show() : console.warn('[sdd] show 대상 미해결: ' + "srch_fil_ods"));
        scwin.selectBox2(sysTpCd);
    } else {
        ($c.util.getComponent("srch_fil_ods") && $c.util.getComponent("srch_fil_ods").hide ? $c.util.getComponent("srch_fil_ods").hide() : console.warn('[sdd] hide 대상 미해결: ' + "srch_fil_ods"));
        $c.util.getComponent("slc_notiTp").setValue('');
        $c.util.getComponent("slc_corpUsrTpCd").setValue('');
    }
};
